#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int mn(int a, int b) {
    return a < b ? a : b;
}
int mx(int a, int b) {
    return a > b ? a : b;
}
int read(void) {
    int x = 0;
    if (scanf("%d", &x) != 1) return 0;
    return x;
}
int readstr(int* a) {
    char s[20001];
    if (scanf("%20000s", s) != 1) return 0;
    if (strcmp(s, "-") == 0) return 0;
    int n = (int)strlen(s);
    for (int i = 0; i < n; i++) a[i] = (unsigned char)s[i];
    return n;
}
void emit(int x) {
    printf("%d ", x);
}
void emitstr(int* a, int n) {
    // 有效长度为零时按平台约定输出 -，否则输出 a 的前 n 个字符。
    if (n == 0) putchar('-');
    for (int i = 0; i < n; i++) putchar(a[i]);
    putchar(' ');
}
int main(void) {
    static int a[20000];
    static int b[20000];
    static int d[20000];
    static int e[20000];
    int i = 0, j = 0, k = 0, m = 0, n = 0;
    // 先读字符串数；第一个字符串保存在 a，后续只缩短它的有效前缀。
    m = read();
    n = readstr(a);
    for (j = 1; j < m; j += 1) {
        k = readstr(b);
        // 公共前缀不能比新字符串更长，先限制比较范围。
        n = mn(n, k);
        i = 0;
        // 从开头连续比较；遇到第一处不同就不能再扩大前缀。
        while ((i < n) && (a[i] == b[i])) {
            i = (i + 1);
        }
        n = i;
    }
    if (n == 0) {
        emitstr(a, 0);
    }
    else {
        emitstr(a, n);
    }
    return 0;
}

