use std::io::{self, Read};
fn mn(a: i32, b: i32) -> i32 {
    a.min(b)
}
fn mx(a: i32, b: i32) -> i32 {
    a.max(b)
}
fn emit(x: i32) {
    print!("{} ", x);
}
fn emitstr(a: &Vec<i32>, n: i32) {
    // 有效长度为零时按平台约定输出 -，否则输出 a 的前 n 个字符。
    if n == 0 {
        print!("-");
    }
    for i in 0..n {
        print!("{}", a[i as usize] as u8 as char);
    }
    print!(" ");
}
struct Reader {
    t: Vec<String>,
    p: usize,
}
impl Reader {
    fn new() -> Self {
        let mut s = String::new();
        io::stdin().read_to_string(&mut s).unwrap();
        Self {
            t: s.split_whitespace().map(String::from).collect(),
            p: 0,
        }
    }
    fn read(&mut self) -> i32 {
        let x = self.t[self.p].parse().unwrap();
        self.p += 1;
        x
    }
    fn readstr(&mut self, a: &mut Vec<i32>) -> i32 {
        let s = &self.t[self.p];
        self.p += 1;
        if s == "-" {
            return 0;
        }
        for (i, c) in s.bytes().enumerate() {
            a[i] = c as i32;
        }
        s.len() as i32
    }
}
fn main() {
    let mut reader = Reader::new();
    let mut a = vec![0i32; 20000];
    let mut b = vec![0i32; 20000];
    let mut d = vec![0i32; 20000];
    let mut e = vec![0i32; 20000];
    let mut i: i32 = 0;
    let mut j: i32 = 0;
    let mut k: i32 = 0;
    let mut m: i32 = 0;
    let mut n: i32 = 0;
    // 先读字符串数；第一个字符串保存在 a，后续只缩短它的有效前缀。
    m = reader.read();
    n = reader.readstr(&mut a);
    j = 1;
    while j < m {
        k = reader.readstr(&mut b);
        // 公共前缀不能比新字符串更长，先限制比较范围。
        n = mn(n, k);
        i = 0;
        // 从开头连续比较；遇到第一处不同就不能再扩大前缀。
        while ((i < n) && (a[(i) as usize] == b[(i) as usize])) {
            i = (i + 1);
        }
        n = i;
        j += 1;
    }
    if (n == 0) {
        emitstr(&a, 0);
    } else {
        emitstr(&a, n);
    }
}
